# -*- coding: utf-8 -*-
"""French, Spanish, and Portuguese narratives, translated from the English copy."""


def register(add):
    # ----- French -----------------------------------------------------------
    add(1, "fr",
        title="Fonction de la main dans l'AVC aigu : essai randomisé d'un entraînement assisté par robot à l'hôpital NP Brain",
        desc="Essai randomisé de 30 patients à l'hôpital NP Brain : un entraînement robotisé de la main s'ajoute à la thérapie neurodéveloppementale. Les résultats au Nine-Hole Peg Test, à l'ABILHAND et à l'indice de Barthel sont ceux de l'étude.",
        lead="Après un AVC, la main revient souvent aux gestes du quotidien plus lentement que la marche : une tasse, un bouton ou un couvert devient un obstacle précis. La fenêtre aiguë évolue vite, et ce qu'on y ajoute doit se mesurer par une comparaison randomisée, non par l'impression d'un cas. En 2026, Scientific Reports a publié un essai randomisé de l'hôpital NP Brain, en Turquie, qui ajoutait un entraînement de la main assisté par un robot Syrebo à la thérapie neurodéveloppementale habituelle. L'article rapporte des gains plus importants en dextérité, en activités bimanuelles et en autonomie que la thérapie seule. L'échantillon compte 30 personnes, et la spasticité n'a pas séparé les groupes.",
        bg=[
            "La main est difficile parce qu'elle exige de la force, un mouvement fractionné et un usage réel. La marche peut se travailler comme une seule cible ; la main doit saisir et lâcher dans une posture instable. La thérapie neurodéveloppementale est déjà la base de la rééducation en phase aiguë, mais un thérapeute ne peut pas répéter chaque prise sans limite : la dose et la régularité sont difficiles à étendre.",
            "Un gant robotique souple peut, en principe, fournir ces répétitions sous supervision. Les patients en phase aiguë changent encore. Savoir si l'appareil peut être ajouté sans incident, et si les scores fonctionnels bougent avec lui, est une question contrôlée. Cet essai porte sur ce stade, plutôt que de répéter une étude de phase chronique.",
        ],
        device="L'article désigne l'appareil comme une main robotique SYREBO. La photographie montre un gant souple, une console et une tablette, pour que le lecteur voie le format. Les détails de modèle appartiennent à l'article et au protocole clinique.",
        design="Comparaison randomisée monocentrique. Un groupe a reçu l'entraînement assisté par robot en plus de la thérapie neurodéveloppementale (NT). Le groupe témoin n'a reçu que la NT. Les critères étaient la dextérité fine, les activités quotidiennes bimanuelles et l'autonomie, pas la force seule.",
        sample="L'hôpital NP Brain a inclus 30 personnes en phase aiguë et les a réparties au hasard. Les séances assistées avaient lieu trois fois par semaine pendant huit semaines. Des mesures de spasticité ont aussi été recueillies.",
        result="L'article rapporte de plus grandes améliorations dans le groupe assisté au Nine-Hole Peg Test, au questionnaire ABILHAND et à l'indice de Barthel. C'est un résultat entre groupes dans cet échantillon. Ce n'est pas une vitesse de récupération promise. La spasticité n'a pas montré de différence significative entre les groupes : toutes les mesures ne se sont donc pas écartées.",
        sig=[
            "L'intérêt tient au moment : la pratique assistée a été testée en phase aiguë, face à une thérapie neurodéveloppementale en cours, et non empruntée à des résultats de phase chronique. Trois mesures fonctionnelles qui bougent ensemble informent davantage qu'un score isolé.",
            "Trente patients randomisés ne soutiennent qu'une lecture prudente. L'essai ne répond pas à l'usage prolongé à domicile, et il ne montre pas que chaque sous-type d'AVC suit la même trajectoire. Le clinicien qui suit la personne fixe encore le plan.",
        ],
        limit="Petit échantillon (n=30). Pas de différence significative entre groupes pour la spasticité. Les changements de score sont le rapport de l'étude, pas une promesse individuelle.")

    add(2, "fr",
        title="Fonction de la main après un AVC : essai randomisé en simple aveugle d'un gant robotique souple et de la thérapie miroir, avec suivi à 6 mois",
        desc="Journal of Rehabilitation Medicine, 2025 : 49 participants, gant robotique souple contre thérapie miroir, huit semaines puis suivi à six mois. Les valeurs de P entre groupes sont celles de l'article.",
        lead="La thérapie miroir utilise l'entrée visuelle pour solliciter le côté atteint. Un gant robotique souple utilise un actionnement souple pour répéter l'ouverture et la fermeture. Savoir quel changement dure le plus longtemps ne se tranche pas le dernier jour d'entraînement. Un essai randomisé en simple aveugle, publié en 2025 dans le Journal of Rehabilitation Medicine, a comparé les deux approches pendant huit semaines et suivi les personnes jusqu'à six mois. L'article rapporte des gains entre groupes statistiquement significatifs en faveur du gant au Box and Block Test, à la force de préhension et au FMA-UE en fin d'entraînement, et indique que ces gains du groupe gant étaient encore présents à six mois.",
        bg=[
            "La question qui compte après un entraînement de la main est de savoir si le changement est encore là une fois la personne rentrée chez elle. La thérapie miroir est simple et dépend de l'attention portée au membre reflété. Un gant déplace la répétition vers un actionneur externe, avec une autre demande d'attention et d'endurance. Les deux sont des méthodes de rééducation. Il ne s'agit pas d'un classement de marques.",
            "Un score le dernier jour d'entraînement peut confondre un stimulus bref et un changement stable. Une comparaison randomisée avec une visite à six mois est ce qui rend cette distinction possible.",
        ],
        device="La photographie de la chronique montre un montage d'entraînement miroir E12. L'appareil de l'étude est celui que l'article précise ; la photo n'est pas une correspondance de modèle.",
        design="Randomisation en simple aveugle d'un gant robotique souple contre la thérapie miroir. Les critères étaient la dextérité de saisie et de lâcher (Box and Block), la force de préhension et le mouvement du membre supérieur (FMA-UE), avec une visite six mois après l'entraînement.",
        sample="Quarante-neuf personnes après un AVC ont été randomisées. L'entraînement a duré huit semaines. L'enregistrement est NCT05898971.",
        result="En fin d'entraînement, l'article rapporte des différences entre groupes en faveur du gant : Box and Block P=0,004, préhension P=0,011, FMA-UE P=0,021. À six mois, les gains du groupe gant étaient encore présents. Ces valeurs de P décrivent cet échantillon. Elles n'attribuent pas une ampleur de récupération à chaque patient.",
        sig=[
            "L'information supplémentaire est le temps. La différence entre groupes n'avait pas disparu à la visite de suivi. C'est plus utile en clinique qu'un classement au dernier jour d'entraînement.",
            "Quarante-neuf personnes restent un petit essai. Les différences initiales, le côté de la lésion et la pratique après la sortie peuvent tous faire bouger un score à six mois. Le résultat appartient à cette population et à ce contraste.",
        ],
        limit="Petit échantillon (n=49). Les valeurs de P et le maintien des gains sont le rapport de l'étude, pas une promesse de produit.")

    add(3, "fr",
        title="Négligence unilatérale en phase subaiguë : comparaison randomisée d'un entraînement miroir robotisé sur le SY-HRE12",
        desc="NeuroRehabilitation, 2025 : 24 personnes en phase subaiguë, toutes avec le SY-HRE12. Mode miroir contre mouvement passif préréglé, 30 minutes, trois fois par semaine, pendant cinq semaines.",
        lead="Certaines personnes en phase subaiguë n'ont pas seulement une main faible. Elles peuvent aussi négliger un côté de l'espace, et l'humeur peut en souffrir. L'entraînement miroir robotisé projette la main la moins atteinte sur la main atteinte, de sorte que la vision et le mouvement arrivent dans la même répétition. Un essai randomisé de 2025 dans NeuroRehabilitation a comparé deux façons d'utiliser le même gant souple : sa fonction miroir, et un mode passif préréglé. L'article rapporte un avantage de l'entraînement miroir sur des critères liés à la négligence et à la dépression. L'échantillon compte 24 personnes.",
        bg=[
            "La négligence rend les scores difficiles à lire. Le problème n'est pas seulement que la main ne se lève pas : l'attention vers un côté de l'espace est réduite. Un miroir classique peut suggérer que la main atteinte bouge alors qu'elle ne bouge pas. Le miroir robotisé cherche à faire bouger le gant atteint avec l'autre main, pour que voir et faire occupent le même essai.",
            "Si les groupes avaient utilisé des appareils différents, toute différence pourrait venir du matériel. Cet essai a donné le SY-HRE12 aux deux groupes et n'a changé que le mode. La question est la façon dont le gant était entraîné, pas la présence d'une nouvelle machine.",
        ],
        device="L'article a utilisé le SYREBO SY-HRE12. La photographie montre une console E12, un gant motorisé et un gant miroir, afin que le système soit reconnaissable. L'appareil de l'étude est le SY-HRE12.",
        design="Comparaison randomisée. Les deux groupes ont utilisé le SY-HRE12. Un groupe a utilisé la fonction miroir. L'autre a utilisé le mouvement passif préréglé. Les critères comprenaient la négligence unilatérale, des mesures liées à la dépression et les activités quotidiennes.",
        sample="Vingt-quatre personnes en phase subaiguë, 12 dans chaque groupe. Les séances duraient 30 minutes, trois fois par semaine, pendant cinq semaines.",
        result="Dans cet échantillon, l'article rapporte un avantage de l'entraînement miroir robotisé sur le mouvement passif préréglé pour les critères liés à la négligence et à la dépression. C'est une différence entre deux modes d'un même appareil. Cela ne signifie pas que le gant traite la négligence ou la dépression. La condition témoin n'était pas une boîte miroir ordinaire.",
        sig=[
            "La question se déplace de « faut-il utiliser un gant » à « quel mode du même gant ». Pour des personnes qui ont aussi une négligence et un poids sur l'humeur, c'est une question clinique plus précise.",
            "Vingt-quatre participants ne soutiennent qu'une lecture prudente. L'essai ne teste pas l'usage à domicile sans supervision, et il n'offre pas un changement garanti de l'attention ou de l'humeur.",
        ],
        limit="Petit échantillon (12 par groupe). Le mode témoin était un mouvement passif préréglé, pas une boîte miroir. Les différences sont le rapport de l'étude.")

    add(4, "fr",
        title="Préhension et scores moteurs après un AVC : essai randomisé de gants d'entraînement robotisés",
        desc="SPORT TK, 2025 : 30 participants. Différences moyennes rapportées : préhension 1,87 (IC 95 % 0,39–3,35, P=0,015) et Fugl-Meyer 16,67 (IC 95 % 3,9–29,4, P=0,012). Aucun modèle n'est nommé.",
        lead="Après un AVC, les cliniciens séparent souvent la main en deux problèmes pratiques : peut-elle saisir, et peut-elle bouger avec contrôle. Un essai randomisé de 2025 dans SPORT TK-EuroAmerican Journal of Sport Sciences a mesuré les deux. L'article rapporte des différences moyennes entre groupes statistiquement significatives en faveur des gants d'entraînement robotisés, pour la préhension et pour le score moteur de Fugl-Meyer. Trente personnes ont participé, et l'article ne nomme pas de modèle commercial.",
        bg=[
            "Un changement de préhension ne produit pas forcément un mouvement utilisable, et un score moteur plus élevé ne signifie pas qu'une personne peut soulever une tasse. Mesurer la force et le mouvement dans la même comparaison randomisée évite de ne publier que le plus favorable des deux.",
            "Les articles sur les gants omettent souvent le modèle. Sans modèle, un résultat ne peut pas être recopié sur une fiche produit. Ce résumé reste donc sur les contrastes que l'article donne réellement.",
        ],
        device="",
        design="Comparaison randomisée d'une pratique avec gant d'entraînement robotisé contre une condition témoin. Les critères communs étaient la préhension et le score moteur de Fugl-Meyer, rapportés comme différences moyennes avec intervalles de confiance à 95 %.",
        sample="Trente personnes après un AVC, 15 dans chaque groupe. L'article n'identifie pas de modèle commercialisé. La photographie générique du gant est une illustration, pas une identification d'appareil.",
        result="Les différences moyennes entre groupes rapportées sont : préhension 1,87 (IC 95 % 0,39 à 3,35, P=0,015) et Fugl-Meyer 16,67 (IC 95 % 3,9 à 29,4, P=0,012). Une différence moyenne n'est pas le gain de chaque personne. L'intervalle du score moteur est large, ce qui est l'aspect d'un petit échantillon lorsque l'estimation est imprécise.",
        sig=[
            "Publier à la fois la différence et l'intervalle est plus utilisable que la phrase « meilleur que le témoin ». La direction est visible, et l'incertitude aussi.",
            "Comme aucun modèle n'est nommé, le résultat ne peut pas être raconté comme une spécification ou une indication d'un gant Syrebo particulier. Trente personnes laissent aussi de la place au bruit d'échantillonnage.",
        ],
        limit="Petit échantillon (n=30). Aucun modèle n'est identifié, et la photo n'est pas une correspondance. Les différences moyennes et les valeurs de P sont les statistiques de l'étude.")

    add(5, "fr",
        title="Fonction de la main en phase subaiguë précoce : essai pilote randomisé en simple aveugle du SY-HR03E par l'équipe de Huashan",
        desc="Essai pilote randomisé en simple aveugle dans BioMedical Engineering OnLine : 20 patients hospitalisés, SY-HR03E, quatre semaines. L'article rapporte un achèvement complet, l'absence d'événements indésirables et des signaux préliminaires sur les scores de la main et les activités quotidiennes.",
        lead="En phase subaiguë précoce, la première question n'est pas de combien de points un score pourrait monter. C'est de savoir si les séances peuvent être terminées, et si elles sont sûres. Une équipe dirigée par le professeur Jia Jie, à l'hôpital Huashan de l'université Fudan, a publié dans BioMedical Engineering OnLine un essai pilote randomisé en simple aveugle sur le Syrebo SY-HR03E pour la rééducation de la main dans cette fenêtre. L'article rapporte que les 20 participants ont terminé quatre semaines, sans abandon et sans événement indésirable. Les scores de la main se sont améliorés dans les deux groupes, avec un changement plus grand dans le groupe gant. Un changement intra-groupe des activités quotidiennes a atteint la signification statistique dans le groupe gant.",
        bg=[
            "Le bras et la main récupèrent en général plus tard que la marche. Manger, s'habiller et se laver dépendent d'un mouvement fractionné des doigts, pas d'un seul chiffre de force. La thérapie conventionnelle de la main aide, mais le nombre de répétitions qu'un thérapeute peut délivrer est limité, et le même mouvement est difficile à répéter au lit.",
            "Un gant pneumatique peut fléchir et étendre les doigts avec peu de masse sur la main, ce qui explique que l'usage au lit soit discuté. Les personnes en phase subaiguë précoce récupèrent aussi spontanément. Tout « effet préliminaire » doit se lire sur ce fond. Un essai pilote randomisé sert à montrer qu'un protocole est faisable et à laisser un signal pour une étude plus grande. Il ne remplace pas un essai de confirmation.",
        ],
        device="L'article décrit le SY-HR03E comme un gant souple commercial accompagné d'un boîtier de table. La masse rapportée est d'environ 3,5 kg pour le système et d'environ 110 g pour le gant. Des soufflets pneumatiques au dos de la main assistent la flexion et l'extension. Des capteurs de pression surveillent le changement produit lorsque la personne essaie de bouger ; au-dessus d'un seuil préréglé de 0,7 kPa, le boîtier traite ce changement comme une intention de mouvement et gonfle ou dégonfle. Le mode visé est l'assistance active, pas une traction entièrement passive.",
        design="Randomisation pilote en simple aveugle. Le groupe robotisé ajoutait l'ouverture et la fermeture assistées par le gant à la rééducation standard. Le groupe conventionnel recevait une thérapie traditionnelle de la main de même durée de séance. Les deux groupes recevaient aussi une heure par jour de rééducation standard. Un thérapeute surveillait la posture. Registre : ChiCTR2000034614.",
        sample="Vingt patients hospitalisés, de 7 jours à 3 mois après le début, 10 dans chaque groupe. Les séances de gant duraient 30 minutes par jour, cinq jours par semaine, pendant quatre semaines. Chaque ouverture-fermeture était maintenue environ trois secondes. Les affiliations des auteurs comprennent l'équipe clinique et, comme l'article le déclare, Shanghai Siyi Intelligent Technology. Cette relation fait partie de la lecture.",
        result="L'article rapporte que les 20 personnes ont terminé quatre semaines, sans abandon et sans événement indésirable. Les scores de Fugl-Meyer de la main se sont améliorés dans les deux groupes, avec une amélioration plus grande dans le groupe robotisé. À l'indice de Barthel modifié, seul le changement intra-groupe du groupe robotisé est rapporté comme statistiquement significatif (p<0,001) ; le changement intra-groupe du groupe conventionnel ne l'est pas. Le stade de Brunnstrom de la main a lui aussi montré un changement intra-groupe significatif seulement dans le groupe robotisé. Dans un pilote de 10 contre 10, une valeur de P intra-groupe est un signal, pas la preuve que la fonction quotidienne augmentera pour les patients en général.",
        sig=[
            "Beaucoup d'études de gants souples incluent des personnes en phase chronique. Ce pilote déplace la question de faisabilité et de sécurité dans la fenêtre de 7 jours à 3 mois. Il ne déplace pas plus tôt des affirmations d'efficacité de phase chronique.",
            "Les scores de la main et ceux des activités quotidiennes n'ont pas pris la même forme statistique : l'article rapporte un changement intra-groupe significatif du Barthel seulement dans le groupe gant. Cet écart mérite d'être retesté. Ce n'est pas l'affirmation que les activités de la vie quotidienne ont été résolues. Un gant de 110 g et une détection d'intention rendent possibles une discussion au lit puis, plus tard, à domicile. Cette étude elle-même a été faite chez des patients hospitalisés.",
        ],
        limit="Randomisation pilote, 10 par groupe. Les signaux préliminaires demandent un échantillon plus grand. La valeur de P est le rapport de l'article pour ce critère. Une affiliation liée à l'appareil est déclarée et doit être pesée.")

    add(6, "fr",
        title="Atteinte de la main avec syndrome de stase de glaires : étude à quatre bras et 200 personnes d'un gant associé à l'électroacupuncture",
        desc="Journal of Hunan University of Chinese Medicine : 200 participants, quatre bras. Les taux d'efficacité globale rapportés étaient 88 %, 76 %, 77,6 % et 70,8 %. Ces chiffres sont le composite de l'étude, pas un taux de produit.",
        lead="Mettre un gant robotisé et l'électroacupuncture dans un même plan est un choix intégratif précis, et le résultat doit rester attaché au bras qui l'a produit. Une étude à quatre bras de 2022, dans le Journal of Hunan University of Chinese Medicine, a inclus 200 personnes avec une atteinte de la main après un AVC du syndrome phlegm-stasis blocking collaterals, et a comparé gant plus électroacupuncture, gant seul, électroacupuncture seule et rééducation habituelle. Les « taux d'efficacité globale » propres à l'article sont 88 %, 76 %, 77,6 % et 70,8 %. Ce composite est le résumé des auteurs. Ce n'est pas un taux d'efficacité de produit.",
        bg=[
            "Sous ce diagnostic de syndrome, les parcours combinent souvent la rééducation moderne et l'électroacupuncture. Une disposition à quatre bras peut montrer la combinaison, l'appareil seul, l'acupuncture seule et les soins habituels sur une même échelle, au lieu d'une histoire avant-après sans contraste.",
            "Un taux d'efficacité globale ramène plusieurs jugements à un pourcentage. Il sert à un contraste grossier et ne sert pas de changement d'une personne sur une échelle nommée. Il ne peut pas être cité comme « l'efficacité du gant est de 88 % ».",
        ],
        device="",
        design="Quatre bras : gant robotisé plus électroacupuncture, gant seul, électroacupuncture seule, et rééducation habituelle. Le critère discuté ici est le taux d'efficacité globale de l'article. Les affiliations comprennent Shanghai Siyi Intelligent Technology, avec Yin Ganggang comme coauteur. Cette déclaration reste dans la lecture.",
        sample="Deux cents personnes avec une atteinte de la main après un AVC, dans le syndrome phlegm-stasis blocking collaterals. C'est le plus grand échantillon de la chronique. L'article ne nomme pas de modèle qui puisse être apparié à un produit actuel, et la photographie générique n'est pas un tel appariement.",
        result="Les taux d'efficacité globale rapportés sont 88 % pour le gant plus électroacupuncture, 76 % pour le gant seul, 77,6 % pour l'électroacupuncture seule et 70,8 % pour la rééducation habituelle. Un composite plus élevé dans le bras combiné signifie seulement que, selon la règle de cette étude, ce bras a obtenu un score plus haut. Il n'attribue pas 88 % au gant, et 76 % n'est pas un taux de produit. Les chiffres du gant seul et de l'électroacupuncture seule sont proches, ce qui va aussi contre l'idée d'expliquer tout le motif par un seul composant.",
        sig=[
            "Deux cents personnes et quatre bras donnent un composite comparable, pas un pourcentage pour une page produit. Lu comme taux d'efficacité globale, les écarts entre combinaison, modalités isolées et soins habituels sont limités.",
            "L'article, tel qu'il est résumé ici, ne fournit pas les mêmes différences moyennes que les autres essais de la chronique. Tant que ces échelles ne sont pas sur la table, l'étude porte sur la façon dont les composants ont été combinés, pas sur le nombre de points dont un score de la main va monter.",
        ],
        limit="Les pourcentages sont les taux d'efficacité globale propres à l'étude. Le bras combiné ne peut pas être attribué au gant seul ni à l'électroacupuncture seule. Aucun modèle n'est nommé.")

    add(7, "fr",
        title="Rééducation de la main après un infarctus de l'artère cérébrale moyenne : cas d'une patiente de 66 ans",
        desc="Cas clinique dans Cureus : une femme de 66 ans avec un infarctus bilatéral du territoire de l'artère cérébrale moyenne a reçu un programme de gant Syrebo sous supervision clinique. Un cas unique n'est pas un résultat général.",
        lead="Un essai randomisé décrit une différence moyenne. Un cas clinique décrit comment la rééducation a été organisée pour une personne. En 2024, dans Cureus, Sharma et ses collègues ont rapporté une femme de 66 ans avec un infarctus des territoires de l'artère cérébrale moyenne, qui a reçu une neurophysiothérapie construite autour d'un programme de gant Syrebo. Le rapport suit le cours de l'observation et du changement fonctionnel. C'est un cas, et il ne se généralise pas.",
        bg=[
            "Un infarctus de ce territoire touche souvent le bras et la main en même temps que le langage ou la cognition, de sorte que le plan dépasse une main faible. Les familles ont en général besoin de savoir quand la pratique du gant s'insérait dans la physiothérapie, et qui la supervisait, plus que d'un pourcentage.",
            "Un cas clinique peut écrire cette séquence. Il n'a pas de témoin parallèle, donc tout changement avant-après mélange la récupération spontanée, les soins habituels et le gant. Ces pièces ne peuvent pas être séparées.",
        ],
        device="L'article discute un programme de gant Syrebo et ne nomme pas de modèle. La photographie du gant et de la console est la figure 2 de ce rapport en accès ouvert (CC BY 4.0), montrée dans l'extrait en tête. Ce n'est pas une figure d'une autre revue.",
        design="Rapport d'un cas unique, pas un essai randomisé. Une fois la personne stable sur le plan médical, les cliniciens ont délivré une neurophysiothérapie qui incluait le programme de gant Syrebo.",
        sample="Une femme de 66 ans avec un infarctus bilatéral du territoire de l'ACM. Le rapport consigne des observations et un changement fonctionnel. Il ne fournit pas de statistiques entre groupes.",
        result="La valeur du rapport est le cours des soins, pas un taux d'amélioration. Il montre comment un gant souple a été placé dans la rééducation d'une personne avec un infarctus sévère, sous supervision professionnelle. Un changement dans un cas unique n'est pas un degré de récupération promis.",
        sig=[
            "Dans une chronique surtout faite d'essais randomisés, un cas clinique est là pour montrer comment un programme a été utilisé pour une personne. Il comble un vide narratif. Il n'élève pas le niveau de preuve.",
            "Un cas ne peut pas estimer la fréquence des événements indésirables, et il ne peut pas dire si la phase aiguë, subaiguë ou chronique convient mieux. Ces questions restent aux études contrôlées.",
        ],
        limit="Cas unique. Pas un effet général. Le changement fonctionnel ne peut pas être attribué au gant seul.")

    add(8, "fr",
        title="Atteinte du membre supérieur après un AVC : étude randomisée de 60 personnes sur la thérapie miroir innovante",
        desc="New Medicine, 2024 : 60 personnes, quatre semaines. L'article rapporte des gains plus grands au FMA-UE, au FMA-WH et à l'indice de Barthel modifié avec la thérapie miroir innovante qu'avec la thérapie miroir conventionnelle.",
        lead="La thérapie miroir conventionnelle utilise un miroir pour suggérer que la main atteinte bouge. La version innovante demande à un gant robotisé de porter la main atteinte dans la même action que le miroir montre, de sorte que voir et faire partagent la séance. En 2024, New Medicine a publié une étude randomisée de Chen et ses collègues qui comparait les deux versions chez 60 personnes pendant quatre semaines. L'article rapporte des gains plus grands pour la thérapie miroir innovante sur le mouvement du membre supérieur, le mouvement poignet-main et les activités quotidiennes.",
        bg=[
            "La thérapie miroir a une limite connue : si la main atteinte ne bouge pas, la suggestion visuelle n'a pas d'entrée motrice appariée. Relier une flexion et une extension assistées à la tâche du miroir est une tentative pour que le côté atteint accomplisse réellement un mouvement dans une amplitude fixée par le thérapeute.",
            "Savoir si ce changement apparaît sur les scores doit se tester contre la thérapie miroir conventionnelle, pas contre le fait de ne rien faire. Soixante personnes, réparties également, constituent une taille randomisée préliminaire.",
        ],
        device="Une image d'entraînement sur la page de la revue montre une marque Yisheng (羿生). La chronique relie cette marque au SY-HR08E des documents officiels et montre une photographie de produit avec écran, console et gant. Ce lien est une note d'identification, pas une revendication de modèle imprimée comme enregistrement d'essai.",
        design="Répartition par nombres aléatoires. La thérapie miroir innovante, qui combine une tâche miroir et un gant robotisé, a été comparée à la thérapie miroir conventionnelle. Les critères comprenaient le FMA-UE, le FMA-WH et l'indice de Barthel modifié.",
        sample="Soixante personnes avec une atteinte du membre supérieur après un AVC, 30 dans chaque groupe, pendant quatre semaines.",
        result="L'article rapporte une plus grande amélioration pour la thérapie miroir innovante au FMA-UE, au FMA-WH et à l'indice de Barthel modifié. C'est la description entre groupes de l'étude. Les moyennes et les valeurs de P ne sont pas recalculées sur cette page ; tant que la page de la revue est encore vérifiée, ces chiffres restent dans l'article.",
        sig=[
            "La question est de savoir si l'ajout d'un mouvement assisté qui correspond au miroir change les scores par rapport au miroir seul. Soixante personnes fournissent un contraste préliminaire, pas une preuve de programme à domicile.",
            "Relier l'image de la revue au SY-HR08E aide seulement le lecteur à reconnaître l'appareil. Savoir si la différence de score est stable attend une vérification indépendante des chiffres complets.",
        ],
        limit="Trente personnes par groupe. Les différences suivent l'article. Les moyennes et les valeurs de P ne sont pas recalculées ici. Le lien de modèle est un contrôle entre la figure de la revue et les documents officiels.")

    add(9, "fr",
        title="Hémiparésie gauche après un infarctus de l'ACM : un dossier de stimulation faradique associée à une main robotisée",
        desc="Cas dans l'IJPRCP : un homme de 60 ans avec hémiparésie gauche a commencé une stimulation faradique plus le Syrebo C12 environ trois mois après l'AVC, cinq fois par semaine pendant quatre semaines. Un cas combiné n'est attribué à aucun des deux composants.",
        lead="Une main hémiparétique reçoit parfois deux entrées à la fois : une stimulation électrique visant le muscle, et une main robotisée pour ouvrir et fermer les doigts. Un cas de 2025 dans l'International Journal of Physiotherapy Research and Clinical Practice consigne quatre semaines de stimulation faradique plus un Syrebo C12 chez un homme avec hémiparésie gauche. C'est le dossier d'un plan combiné, pas un essai d'efficacité de l'une ou l'autre pièce.",
        bg=[
            "Des mois après un AVC, le changement de la main est en général plus lent, et les cliniciens ajoutent parfois une stimulation ou une assistance externe à la pratique ordinaire. Une fois les deux utilisés, un changement avant-après ne peut pas être donné proprement à l'un ou à l'autre.",
            "Le rapport reste utile. Il indique quand le plan a commencé, à quelle fréquence il a eu lieu, et quel appareil était dans la pièce. Il ne donne pas de taux, et il ne donne pas de différence contre un témoin.",
        ],
        device="L'appareil robotisé du rapport est le Syrebo C12. La photographie est un recadrage de la page produit officielle du C12, pour que la console et le gant soient reconnaissables. Elle n'ajoute pas de spécifications que l'article a omises.",
        design="Une intervention combinée unique : stimulation faradique ensemble avec la pratique de la main robotisée Syrebo C12. Il n'y a pas de groupe témoin parallèle.",
        sample="Un homme de 60 ans avec hémiparésie gauche. Le plan a commencé 3 mois et 2 semaines après l'AVC, cinq fois par semaine, pendant quatre semaines.",
        result="Cette page ne réimprime pas de scores fonctionnels qui n'ont pas été vérifiés contre l'article pour la chronique. Ce qui est clair, c'est l'organisation : stimulation et pratique robotisée ont été utilisées ensemble, donc un changement ne peut pas être écrit comme l'effet du C12 seul ou de la stimulation seule.",
        sig=[
            "Le dossier ajoute un calendrier concret : environ trois mois après l'AVC, cinq séances par semaine, deux modalités ensemble. Il n'élève pas le niveau de preuve.",
            "Un cas d'hémiparésie gauche après un infarctus de l'ACM ne tient pas lieu d'autres lésions ou d'autres délais après le début.",
        ],
        limit="Cas combiné unique. Le changement n'est attribué ni au C12 ni à la stimulation, et ce n'est pas un effet général.")

    add(10, "fr",
        title="Une orthèse souple poignet-main : conception et évaluation préliminaire dans Wearable Technologies",
        desc="Ledoux et Barth rapportent leur propre orthèse poignet-main imprimée en 3D dans Wearable Technologies. Cette note reste sur cet article de conception. Elle ne classe pas de produits commerciaux et ce n'est pas un essai d'efficacité.",
        lead="En 2024, Wearable Technologies, aux Cambridge University Press, a publié un article de conception de Ledoux et Barth, à l'université Vanderbilt. L'appareil qu'ils ont construit et évalué de façon préliminaire est leur propre orthèse de préhension poignet-main imprimée en 3D. L'article mentionne des structures souples commerciales en discutant des mains portables. Cette chronique ne transforme pas cette discussion en classement, et elle ne traite pas l'article comme une preuve d'efficacité pour Syrebo.",
        bg=[
            "Un appareil de main qui quitte la salle de thérapie doit répondre au poids, au profil, et à la question de savoir si une personne peut le mettre. Les articles de conception énoncent en général ces contraintes, puis décrivent un prototype. Ils ne rapportent pas d'abord un essai fonctionnel multicentrique. Lire un article de conception comme un article d'efficacité invente des critères cliniques qui n'ont pas été mesurés.",
            "Une structure souple et un exosquelette rigide répondent à des problèmes d'ingénierie différents. La souplesse est une façon de réduire le profil. Parler d'un changement fonctionnel exige encore une étude humaine propre.",
        ],
        device="L'extrait en tête est la première page en accès ouvert (CC BY 4.0), pas un tableau de comparaison. La photographie de produit montre un système de gant clinique Syrebo. Ce n'est pas une figure de cette expérience.",
        design="Conception, modélisation et évaluation préliminaire de l'orthèse imprimée en 3D des auteurs eux-mêmes. L'article n'est pas un essai randomisé de Syrebo et n'est pas une comparaison d'efficacité entre appareils commercialisés.",
        sample="La partie humaine est un regard préliminaire sur le prototype des auteurs. Sa taille et ses tâches sont celles de l'article. Elle n'est pas reformulée ici comme une cohorte Syrebo.",
        result="Cette page ne cite pas d'adjectifs commerciaux et ne liste pas d'autres marques. Ce qui reste, c'est que l'article est une étude de conception en accès ouvert sur une structure souple et portable. Le mot « presumably » des auteurs marque le confort comme quelque chose qu'ils n'ont pas traité comme un critère mesuré.",
        sig=[
            "L'article est dans la chronique pour qu'une étude de conception reste distincte d'un essai d'efficacité. Savoir si une structure souple rend un appareil plus facile à porter au quotidien est une étude de port et une étude fonctionnelle, séparément.",
            "L'accès ouvert permet au lecteur de vérifier le libellé. Le but de la vérification est d'empêcher une présomption de devenir une conclusion, pas d'élire un produit le plus léger.",
        ],
        limit="Pas un essai d'efficacité de Syrebo, et pas un classement de produits. La source nuance le confort avec « presumably ». Le recadrage de la première page n'inclut pas de tableau de comparaison.")

    add(11, "fr",
        title="Robots de doigts destinés au domicile : une note de développement dans le Journal of the Robotics Society of Japan",
        desc="Un article de 2023 du Journal of the Robotics Society of Japan discute des robots de doigts à domicile pour l'hémiparésie et cite Syrebo parmi les rares exemples commercialisés. Ce n'est pas un essai clinique.",
        lead="La rééducation de la main à domicile est discutée depuis des années. Les exemples commercialisés dans la littérature de société restent peu nombreux. En 2023, le Journal of the Robotics Society of Japan a publié un article de Furudate et ses collègues sur un robot de rééducation des doigts destiné à l'usage à domicile après une hémiparésie, et sur son développement avec des cliniciens. Les auteurs notent que les cas commercialisés d'usage à domicile restent rares, et ils citent le gant de main Syrebo comme l'un de ces cas. L'article est une note de développement et de collaboration, pas un essai d'efficacité.",
        bg=[
            "Entre le service et le domicile se trouvent l'enfilage, les limites de sécurité, et l'usage lorsqu'aucun thérapeute n'est dans la pièce. Les articles d'ingénierie placent ces contraintes dans le travail avec les cliniciens. Être nommé signifie que les auteurs ont choisi ce produit comme exemple. Cela ne signifie pas que la société a mené une étude contrôlée.",
            "« Peu ont été commercialisés » est aussi une limite. Le lire comme « la rééducation à domicile est déjà généralement disponible » transforme un exemple en affirmation épidémiologique.",
        ],
        device="L'article n'imprime pas de photographie de gant. L'image du gant et de la console dans cette chronique est la figure 2 du cas Cureus de 2024 de Sharma et ses collègues (CC BY 4.0). La légende le dit. Ce n'est pas la figure originale de l'article de la société japonaise.",
        design="Article de développement dans une revue de société, sur des robots de doigts pour l'usage à domicile et sur le travail avec des cliniciens. Il n'y a pas de randomisation et pas de comparaison fonctionnelle entre groupes.",
        sample="Une taille d'échantillon clinique ne s'applique pas. L'article discute un chemin vers un produit, pas des résultats dans une cohorte.",
        result="L'énoncé, tel qu'il est utilisé ici, est que les robots de doigts commercialisés visant le domicile sont encore peu nombreux, et que Syrebo est un exemple que les auteurs nomment. La chronique garde ce périmètre. Il n'est pas réécrit comme une efficacité, un rang de marché, ou une promesse que l'entraînement à domicile sera mené à terme.",
        sig=[
            "La valeur de la note est que l'usage à domicile est traité comme un problème d'ingénierie défini avec des cliniciens. Un exemple commercialisé montre qu'un appareil est passé du prototype au produit.",
            "Savoir s'il peut être utilisé de façon sûre et répétée à domicile dépend encore de l'indication, de la supervision et d'études cliniques séparées. L'article de société ne fournit pas ces données.",
        ],
        limit="Pas un essai clinique de Syrebo. La source souligne que les exemples commercialisés restent peu nombreux. La photographie vient d'un autre cas en accès ouvert.")

    # ----- Spanish ----------------------------------------------------------
    add(1, "es",
        title="Función de la mano en el ictus agudo: un ensayo aleatorizado de entrenamiento asistido por robot en el Hospital NP Brain",
        desc="Ensayo aleatorizado de 30 pacientes en el Hospital NP Brain: se añadió entrenamiento de la mano asistido por robot a la terapia del neurodesarrollo. Los hallazgos del Nine-Hole Peg, ABILHAND y Barthel se presentan como resultados del estudio.",
        lead="Después de un ictus, la mano suele volver a las tareas diarias más despacio que la marcha: una taza, un botón o un cubierto se convierte en un obstáculo concreto. La ventana aguda cambia deprisa, así que lo que se añade ahí necesita una comparación aleatorizada y no la impresión de un caso. En 2026 Scientific Reports publicó un ensayo aleatorizado del Hospital NP Brain, en Turquía, que añadió entrenamiento de la mano asistido por un robot Syrebo a la terapia del neurodesarrollo convencional. El artículo informa mayores ganancias en destreza, actividades bimanuales y autocuidado que la terapia sola. La muestra es de 30 personas, y la espasticidad no separó los grupos.",
        bg=[
            "La mano es difícil porque necesita fuerza, movimiento fraccionado y uso real. La marcha puede practicarse como un solo objetivo; la mano tiene que agarrar y soltar dentro de una postura inestable. La terapia del neurodesarrollo ya es la base de la rehabilitación aguda, pero un terapeuta no puede repetir cada prensión de forma indefinida, así que la dosis y la constancia son difíciles de ampliar.",
            "Un guante robótico blando puede, en principio, aportar esas repeticiones bajo supervisión. Los pacientes agudos siguen cambiando. Si el dispositivo puede añadirse con seguridad, y si las puntuaciones funcionales se mueven con él, es una pregunta controlada. Este ensayo aborda esa fase, en lugar de repetir un estudio de fase crónica.",
        ],
        device="El artículo nombra el dispositivo como una mano robótica SYREBO. La fotografía muestra un guante blando, una consola y una tableta para que el lector vea el formato. Los detalles del modelo pertenecen al artículo y al protocolo clínico.",
        design="Comparación aleatorizada de un solo centro. Un grupo recibió entrenamiento de la mano asistido por robot más terapia del neurodesarrollo (NT). El grupo de control recibió solo NT. Los resultados fueron la destreza fina, las actividades diarias bimanuales y el autocuidado, no la fuerza por sí sola.",
        sample="El Hospital NP Brain incluyó a 30 personas en fase aguda y las aleatorizó. Las sesiones asistidas fueron tres veces por semana durante ocho semanas. También se recogieron medidas de espasticidad.",
        result="El artículo informa mejoras mayores en el grupo asistido en el Nine-Hole Peg Test, el cuestionario ABILHAND y el índice de Barthel. Es un hallazgo entre grupos en esta muestra. No es una velocidad de recuperación prometida. La espasticidad no mostró una diferencia significativa entre grupos, de modo que no todas las medidas se separaron.",
        sig=[
            "La parte útil es el momento: la práctica asistida se probó en la fase aguda frente a la terapia del neurodesarrollo en curso, y no se tomó prestada de resultados de fase crónica. Que tres medidas funcionales se muevan juntas informa más que una sola puntuación.",
            "Treinta pacientes aleatorizados solo sostienen una lectura cauta. El ensayo no responde al uso prolongado en el domicilio, y no muestra que cada subtipo de ictus siga el mismo camino. El clínico que trata a la persona sigue fijando el plan.",
        ],
        limit="Muestra pequeña (n=30). Sin diferencia significativa entre grupos en la espasticidad. Los cambios de puntuación son el informe del estudio, no una promesa individual.")

    add(2, "es",
        title="Función de la mano tras el ictus: un ECA simple ciego de un guante robótico blando y terapia de espejo, con seguimiento a 6 meses",
        desc="Journal of Rehabilitation Medicine, 2025: 49 participantes, guante robótico blando frente a terapia de espejo, ocho semanas más seguimiento a seis meses. Los valores de P entre grupos son el informe del artículo.",
        lead="La terapia de espejo usa la entrada visual para reclutar el lado afectado. Un guante robótico blando usa un accionamiento flexible para repetir la apertura y el cierre. Qué cambio dura más no puede responderse el último día de entrenamiento. Un ensayo aleatorizado simple ciego de 2025 en el Journal of Rehabilitation Medicine comparó los dos enfoques durante ocho semanas y siguió a las personas hasta los seis meses. El artículo informa ganancias entre grupos estadísticamente significativas a favor del guante en el Box and Block Test, la fuerza de prensión y el FMA-UE al final del entrenamiento, e informa que esas ganancias del grupo del guante seguían presentes a los seis meses.",
        bg=[
            "La pregunta que importa después del entrenamiento de la mano es si el cambio sigue ahí cuando la persona vuelve a casa. La terapia de espejo es sencilla y depende de la atención al miembro reflejado. Un guante traslada la repetición a un actuador externo, con otra exigencia de atención y resistencia. Ambos son métodos de rehabilitación. Esto no es una clasificación de marcas.",
            "Una puntuación el último día de entrenamiento puede confundir un estímulo breve con un cambio estable. Una comparación aleatorizada con una visita a los seis meses es lo que hace posible esa distinción.",
        ],
        device="La fotografía de la columna muestra un montaje de entrenamiento con espejo E12. El dispositivo del estudio es el que especifica el artículo; la foto no es una correspondencia de modelo.",
        design="Aleatorización simple ciego de un guante robótico blando frente a terapia de espejo. Los resultados fueron la destreza de agarre y suelta (Box and Block), la fuerza de prensión y el movimiento del miembro superior (FMA-UE), con una visita seis meses después del entrenamiento.",
        sample="Se aleatorizó a cuarenta y nueve personas tras un ictus. El entrenamiento duró ocho semanas. El registro es NCT05898971.",
        result="Al final del entrenamiento el artículo informa diferencias entre grupos a favor del guante: Box and Block P=0,004, prensión P=0,011, FMA-UE P=0,021. A los seis meses las ganancias del grupo del guante seguían presentes. Esos valores de P describen esta muestra. No asignan un tamaño de recuperación a cada paciente.",
        sig=[
            "La información extra es el tiempo. La diferencia entre grupos no había desaparecido en la visita de seguimiento. Eso es más útil en la clínica que una clasificación el último día de entrenamiento.",
            "Cuarenta y nueve personas siguen siendo un ensayo pequeño. Las diferencias basales, el lado de la lesión y la práctica tras el alta pueden mover una puntuación a los seis meses. El hallazgo pertenece a esta población y a este contraste.",
        ],
        limit="Muestra pequeña (n=49). Los valores de P y el mantenimiento de las ganancias son el informe del estudio, no una promesa de producto.")

    add(3, "es",
        title="Negligencia unilateral en el ictus subagudo: comparación aleatorizada del entrenamiento en espejo robótico con el SY-HRE12",
        desc="NeuroRehabilitation, 2025: 24 personas en fase subaguda, todas con el SY-HRE12. Modo espejo frente a movimiento pasivo predefinido, 30 minutos, tres veces por semana, durante cinco semanas.",
        lead="Algunas personas en fase subaguda tienen algo más que una mano débil. También pueden descuidar un lado del espacio, y el ánimo puede resentirse. El entrenamiento en espejo robótico proyecta la mano menos afectada sobre la afectada, de modo que la visión y el movimiento llegan en la misma repetición. Un ensayo aleatorizado de 2025 en NeuroRehabilitation comparó dos formas de usar el mismo guante blando: su función de espejo y un modo pasivo predefinido. El artículo informa una ventaja del entrenamiento en espejo en resultados relacionados con la negligencia y la depresión. La muestra es de 24 personas.",
        bg=[
            "La negligencia hace que las puntuaciones sean difíciles de leer. El problema no es solo que la mano no se levante; la atención a un lado del espacio está reducida. Un espejo convencional puede sugerir que la mano afectada se mueve cuando no lo hace. El espejo robótico intenta que el guante afectado se mueva con la otra mano, para que ver y hacer ocupen el mismo ensayo.",
            "Si los grupos hubieran usado dispositivos distintos, cualquier diferencia podría ser el hardware. Este ensayo dio el SY-HRE12 a ambos grupos y cambió solo el modo. La pregunta es cómo se accionó el guante, no si había una máquina nueva.",
        ],
        device="El artículo usó el SYREBO SY-HRE12. La fotografía muestra una consola E12, un guante motorizado y un guante de espejo para que el sistema sea reconocible. El dispositivo del estudio es el SY-HRE12.",
        design="Comparación aleatorizada. Ambos grupos usaron el SY-HRE12. Un grupo usó la función de espejo. El otro usó el movimiento pasivo predefinido. Los resultados incluyeron negligencia unilateral, medidas relacionadas con la depresión y actividades diarias.",
        sample="Veinticuatro personas en fase subaguda, 12 en cada grupo. Las sesiones duraron 30 minutos, tres veces por semana, durante cinco semanas.",
        result="En esta muestra el artículo informa una ventaja del entrenamiento en espejo robótico sobre el movimiento pasivo predefinido en resultados relacionados con la negligencia y la depresión. Es una diferencia entre dos modos de un mismo dispositivo. No significa que el guante trate la negligencia o la depresión. La condición de control no era una caja de espejo ordinaria.",
        sig=[
            "El cambio de pregunta va de «si usar un guante» a «qué modo del mismo guante». Para personas que además tienen negligencia y carga anímica, es una pregunta clínica más precisa.",
            "Veinticuatro participantes solo sostienen una lectura cauta. El ensayo no prueba el uso domiciliario sin supervisión, y no ofrece un cambio garantizado de la atención o el ánimo.",
        ],
        limit="Muestra pequeña (12 por grupo). El modo de control fue el movimiento pasivo predefinido, no una caja de espejo. Las diferencias son el informe del estudio.")

    add(4, "es",
        title="Prensión y puntuaciones motoras tras el ictus: un ensayo aleatorizado de guantes de entrenamiento robótico",
        desc="SPORT TK, 2025: 30 participantes. Diferencias medias informadas: prensión 1,87 (IC 95 % 0,39–3,35, P=0,015) y Fugl-Meyer 16,67 (IC 95 % 3,9–29,4, P=0,012). No se nombra un modelo.",
        lead="Tras un ictus, los clínicos suelen dividir la mano en dos problemas prácticos: si puede agarrar y si puede moverse con control. Un ensayo aleatorizado de 2025 en SPORT TK-EuroAmerican Journal of Sport Sciences midió ambos. El artículo informa diferencias medias entre grupos estadísticamente significativas a favor de los guantes de entrenamiento robótico en la prensión y en la puntuación motora de Fugl-Meyer. Participaron treinta personas, y el artículo no nombra un modelo comercial.",
        bg=[
            "Un cambio en la prensión no tiene por qué producir un movimiento útil, y una puntuación motora más alta no significa que una persona pueda levantar una taza. Medir fuerza y movimiento en la misma comparación aleatorizada evita publicar solo el más favorable de los dos.",
            "Los artículos sobre guantes a menudo omiten el modelo. Sin un modelo, un resultado no puede copiarse a una ficha de producto. Este resumen se queda, por tanto, en los contrastes que el artículo realmente da.",
        ],
        device="",
        design="Comparación aleatorizada de la práctica con guante de entrenamiento robótico frente a una condición de control. Los resultados compartidos fueron la prensión y la puntuación motora de Fugl-Meyer, informadas como diferencias medias con intervalos de confianza del 95 %.",
        sample="Treinta personas tras un ictus, 15 en cada grupo. El artículo no identifica un modelo comercializado. La fotografía genérica del guante es una ilustración, no una identificación del dispositivo.",
        result="Las diferencias medias entre grupos informadas son prensión 1,87 (IC 95 % 0,39 a 3,35, P=0,015) y Fugl-Meyer 16,67 (IC 95 % 3,9 a 29,4, P=0,012). Una diferencia media no es la ganancia de cada persona. El intervalo de la puntuación motora es amplio, que es el aspecto de una muestra pequeña cuando la estimación es imprecisa.",
        sig=[
            "Publicar la diferencia y el intervalo es más utilizable que la frase «mejor que el control». La dirección es visible, y también la incertidumbre.",
            "Como no se nombra un modelo, el resultado no puede recontarse como una especificación o una indicación de un guante Syrebo concreto. Treinta personas también dejan sitio al ruido de muestreo.",
        ],
        limit="Muestra pequeña (n=30). No se identifica un modelo, y la foto no es una correspondencia. Las diferencias medias y los valores de P son las estadísticas del estudio.")

    add(5, "es",
        title="Función de la mano en la fase subaguda temprana: un ECA piloto simple ciego del SY-HR03E del equipo de Huashan",
        desc="ECA piloto simple ciego en BioMedical Engineering OnLine: 20 pacientes ingresados, SY-HR03E, cuatro semanas. El artículo informa finalización completa, ausencia de eventos adversos y señales preliminares en puntuaciones de la mano y actividades diarias.",
        lead="En la fase subaguda temprana la primera pregunta no es cuántos puntos podría subir una puntuación. Es si las sesiones pueden terminarse y si son seguras. Un equipo dirigido por el profesor Jia Jie, en el Hospital Huashan de la Universidad Fudan, publicó en BioMedical Engineering OnLine un ensayo piloto aleatorizado simple ciego sobre el Syrebo SY-HR03E para la rehabilitación de la mano en esa ventana. El artículo informa que los 20 participantes terminaron cuatro semanas, sin abandonos y sin eventos adversos. Las puntuaciones de la mano mejoraron en ambos grupos, con un cambio mayor en el grupo del guante. Un cambio intragrupo en las actividades diarias alcanzó significación estadística en el grupo del guante.",
        bg=[
            "El brazo y la mano suelen recuperarse más tarde que la marcha. Comer, vestirse y lavarse dependen de un movimiento fraccionado de los dedos, no de un solo número de fuerza. La terapia convencional de la mano ayuda, pero el número de repeticiones que un terapeuta puede dar es limitado, y el mismo movimiento es difícil de repetir junto a la cama.",
            "Un guante neumático puede flexionar y extender los dedos con poca masa sobre la mano, y por eso se habla del uso junto a la cama. Las personas en fase subaguda temprana también se recuperan de forma espontánea. Cualquier «efecto preliminar» tiene que leerse sobre ese fondo. Un ensayo piloto aleatorizado sirve para mostrar que un protocolo es viable y para dejar una señal a un estudio mayor. No sustituye un ensayo confirmatorio.",
        ],
        device="El artículo describe el SY-HR03E como un guante blando comercial más un controlador de sobremesa. La masa informada es de unos 3,5 kg para el sistema y unos 110 g para el guante. Fuelles neumáticos en el dorso de la mano asisten la flexión y la extensión. Sensores de presión observan el cambio que se produce cuando la persona intenta moverse; por encima de un umbral predefinido de 0,7 kPa el controlador trata ese cambio como intención de movimiento e infla o desinfla. El modo previsto es la asistencia activa, no un arrastre del todo pasivo.",
        design="Aleatorización piloto simple ciego. El grupo robótico añadió apertura y cierre asistidos por el guante a la rehabilitación estándar. El grupo convencional recibió terapia tradicional de la mano de la misma duración de sesión. Ambos grupos recibieron también una hora al día de rehabilitación estándar. Un terapeuta supervisó la postura. Registro: ChiCTR2000034614.",
        sample="Veinte pacientes ingresados, de 7 días a 3 meses tras el inicio, 10 en cada grupo. Las sesiones con guante fueron de 30 minutos al día, cinco días a la semana, durante cuatro semanas. Cada apertura-cierre se mantuvo unos tres segundos. Las afiliaciones de los autores incluyen al equipo clínico y, según declara el artículo, Shanghai Siyi Intelligent Technology. Esa relación forma parte de la lectura.",
        result="El artículo informa que las 20 personas completaron cuatro semanas, sin abandonos y sin eventos adversos. Las puntuaciones de Fugl-Meyer de la mano mejoraron en ambos grupos, con una mejora mayor en el grupo robótico. En el índice de Barthel modificado, solo el cambio intragrupo del grupo robótico se informa como estadísticamente significativo (p<0,001); el cambio intragrupo del grupo convencional no lo es. La etapa de Brunnstrom de la mano también mostró un cambio intragrupo significativo solo en el grupo robótico. En un piloto de 10 frente a 10, un valor de P intragrupo es una señal, no evidencia de que la función diaria vaya a subir en los pacientes en general.",
        sig=[
            "Muchos estudios de guantes blandos incluyen a personas en fase crónica. Este piloto traslada la pregunta de viabilidad y seguridad a la ventana de 7 días a 3 meses. No adelanta afirmaciones de eficacia de la fase crónica.",
            "Las puntuaciones de la mano y las de actividad diaria no tomaron la misma forma estadística: el artículo informa un cambio intragrupo significativo del Barthel solo en el grupo del guante. Esa separación merece volver a probarse. No es una afirmación de que las actividades de la vida diaria estén resueltas. Un guante de 110 g y la detección de intención hacen posible hablar del uso junto a la cama y, más adelante, en el domicilio. Este estudio se hizo con pacientes ingresados.",
        ],
        limit="Aleatorización piloto, 10 por grupo. Las señales preliminares necesitan una muestra mayor. El valor de P es el informe del artículo para ese resultado. Se declara una afiliación relacionada con el dispositivo y debe ponderarse.")

    add(6, "es",
        title="Deterioro de la mano con patrón de estasis de flema: un estudio de cuatro brazos y 200 personas de un guante más electroacupuntura",
        desc="Journal of Hunan University of Chinese Medicine: 200 participantes, cuatro brazos. Las tasas de eficacia total informadas fueron 88 %, 76 %, 77,6 % y 70,8 %. Esas cifras son el compuesto del estudio, no una tasa de producto.",
        lead="Poner un guante robótico y electroacupuntura en un mismo plan es una elección integrativa concreta, y el resultado tiene que seguir unido al brazo que lo produjo. Un estudio de cuatro brazos de 2022 en el Journal of Hunan University of Chinese Medicine incluyó a 200 personas con deterioro de la mano tras un ictus del patrón phlegm-stasis blocking collaterals, y comparó guante más electroacupuntura, guante solo, electroacupuntura sola y rehabilitación habitual. Las «tasas de eficacia total» propias del artículo son 88 %, 76 %, 77,6 % y 70,8 %. Ese compuesto es el resumen de los autores. No es una tasa de eficacia de producto.",
        bg=[
            "Bajo este diagnóstico de patrón, las vías suelen combinar rehabilitación moderna y electroacupuntura. Un diseño de cuatro brazos puede mostrar la combinación, el dispositivo solo, la acupuntura sola y el cuidado habitual en una misma escala, en lugar de una historia antes-después sin contraste.",
            "Una tasa de eficacia total reduce varios juicios a un porcentaje. Sirve para un contraste grueso y no sirve como el cambio de una persona en una escala con nombre. No puede citarse como «la eficacia del guante es del 88 %».",
        ],
        device="",
        design="Cuatro brazos: guante robótico más electroacupuntura, guante solo, electroacupuntura sola y rehabilitación habitual. El resultado que se discute aquí es la tasa de eficacia total del artículo. Las afiliaciones incluyen Shanghai Siyi Intelligent Technology, con Yin Ganggang como coautor. Esa declaración permanece en la lectura.",
        sample="Doscientas personas con deterioro de la mano tras un ictus en el patrón phlegm-stasis blocking collaterals. Es la muestra más grande de la columna. El artículo no nombra un modelo que pueda emparejarse con un producto actual, y la fotografía genérica no es ese emparejamiento.",
        result="Las tasas de eficacia total informadas son 88 % para guante más electroacupuntura, 76 % para el guante solo, 77,6 % para la electroacupuntura sola y 70,8 % para la rehabilitación habitual. Un compuesto más alto en el brazo combinado solo significa que, bajo la regla de este estudio, ese brazo puntuó más. No asigna el 88 % al guante, y el 76 % no es una tasa de producto. Las cifras del guante solo y de la electroacupuntura sola quedan cerca, lo que también argumenta contra explicar todo el patrón por un solo componente.",
        sig=[
            "Doscientas personas y cuatro brazos dan un compuesto comparable, no un porcentaje para una página de producto. Leídas como tasa de eficacia total, las brechas entre combinación, modalidades aisladas y cuidado habitual son limitadas.",
            "El artículo, tal como se resume aquí, no aporta las mismas diferencias medias de los otros ensayos de la columna. Hasta que esas escalas estén sobre la mesa, el estudio trata de cómo se combinaron los componentes, no de cuántos puntos subirá una puntuación de la mano.",
        ],
        limit="Los porcentajes son las tasas de eficacia total propias del estudio. El brazo combinado no puede atribuirse al guante ni a la electroacupuntura por separado. No se nombra un modelo.")

    add(7, "es",
        title="Rehabilitación de la mano tras un infarto de la arteria cerebral media: el caso de una paciente de 66 años",
        desc="Caso clínico en Cureus: una mujer de 66 años con infarto bilateral del territorio de la ACM recibió un programa de guante Syrebo bajo supervisión clínica. Un solo caso no es un resultado general.",
        lead="Un ensayo aleatorizado describe una diferencia media. Un caso clínico describe cómo se organizó la rehabilitación de una persona. En 2024, en Cureus, Sharma y colegas informaron de una mujer de 66 años con infarto en los territorios de la arteria cerebral media que recibió neurofisioterapia construida en torno a un programa de guante Syrebo. El informe sigue el curso de la observación y del cambio funcional. Es un caso, y no se generaliza.",
        bg=[
            "Un infarto de este territorio suele afectar el brazo y la mano junto con el lenguaje o la cognición, así que el plan es más que una mano débil. Las familias suelen necesitar saber cuándo se situó la práctica del guante dentro de la fisioterapia, y quién la supervisó, más que un porcentaje.",
            "Un caso clínico puede escribir esa secuencia. No tiene un control paralelo, así que cualquier cambio antes-después mezcla la recuperación espontánea, el cuidado habitual y el guante. Esas piezas no pueden separarse.",
        ],
        device="El artículo discute un programa de guante Syrebo y no nombra un modelo. La fotografía del guante y la consola es la figura 2 de ese informe de acceso abierto (CC BY 4.0), mostrada en el extracto de arriba. No es una figura de otra revisión.",
        design="Informe de un solo caso, no un ensayo aleatorizado. Cuando la persona estuvo estable desde el punto de vista médico, los clínicos aplicaron neurofisioterapia que incluía el programa de guante Syrebo.",
        sample="Una mujer de 66 años con infarto bilateral del territorio de la ACM. El informe registra observaciones y cambio funcional. No aporta estadísticas entre grupos.",
        result="El valor del informe es el curso de la atención, no una tasa de mejoría. Muestra cómo se colocó un guante blando dentro de la rehabilitación de una persona con un infarto grave, bajo supervisión profesional. Un cambio en un solo caso no es un grado de recuperación prometido.",
        sig=[
            "En una columna hecha sobre todo de ensayos aleatorizados, un caso clínico está aquí para mostrar cómo se usó un programa con una persona. Llena un hueco narrativo. No eleva el nivel de evidencia.",
            "Un caso no puede estimar con qué frecuencia ocurren eventos adversos, y no puede decir si encaja mejor la fase aguda, subaguda o crónica. Esas preguntas siguen en los estudios controlados.",
        ],
        limit="Caso único. No es un efecto general. El cambio funcional no puede asignarse al guante por sí solo.")

    add(8, "es",
        title="Deterioro del miembro superior tras el ictus: un estudio aleatorizado de 60 personas sobre terapia de espejo innovadora",
        desc="New Medicine, 2024: 60 personas, cuatro semanas. El artículo informa mayores ganancias en FMA-UE, FMA-WH y el índice de Barthel modificado con la terapia de espejo innovadora que con la terapia de espejo convencional.",
        lead="La terapia de espejo convencional usa un espejo para sugerir que la mano afectada se mueve. La versión innovadora pide a un guante robótico que lleve la mano afectada por la misma acción que muestra el espejo, de modo que ver y hacer compartan la sesión. En 2024 New Medicine publicó un estudio aleatorizado de Chen y colegas que comparó las dos versiones en 60 personas durante cuatro semanas. El artículo informa mayores ganancias de la terapia de espejo innovadora en el movimiento del miembro superior, el movimiento de muñeca y mano, y las actividades diarias.",
        bg=[
            "La terapia de espejo tiene un límite conocido: si la mano afectada no se mueve, la sugerencia visual no tiene una entrada motora emparejada. Conectar la flexión y la extensión asistidas a la tarea del espejo es un intento de que el lado afectado complete de verdad un movimiento dentro de un rango que fija el terapeuta.",
            "Si ese cambio aparece en las puntuaciones tiene que probarse frente a la terapia de espejo convencional, no frente a no hacer nada. Sesenta personas, repartidas por igual, son un tamaño aleatorizado preliminar.",
        ],
        device="Una imagen de entrenamiento en la página de la revista muestra una marca Yisheng (羿生). La columna relaciona esa marca con el SY-HR08E de los materiales oficiales y muestra una fotografía de producto con pantalla, consola y guante. La relación es una nota de identificación, no una afirmación de modelo impresa como registro del ensayo.",
        design="Asignación por números aleatorios. La terapia de espejo innovadora, que combina una tarea de espejo con un guante robótico, se comparó con la terapia de espejo convencional. Los resultados incluyeron FMA-UE, FMA-WH y el índice de Barthel modificado.",
        sample="Sesenta personas con deterioro del miembro superior tras un ictus, 30 en cada grupo, durante cuatro semanas.",
        result="El artículo informa una mayor mejoría de la terapia de espejo innovadora en FMA-UE, FMA-WH y el índice de Barthel modificado. Es la descripción entre grupos del estudio. Las medias y los valores de P no se recalculan en esta página; mientras se comprueba la página de la revista, esas cifras permanecen en el artículo.",
        sig=[
            "La pregunta es si añadir un movimiento asistido que coincide con el espejo cambia las puntuaciones respecto del espejo solo. Sesenta personas aportan un contraste preliminar, no una prueba de programa domiciliario.",
            "Vincular la imagen de la revista con el SY-HR08E solo ayuda al lector a reconocer el dispositivo. Si la diferencia de puntuación es estable espera una comprobación independiente de las cifras completas.",
        ],
        limit="Treinta personas por grupo. Las diferencias siguen al artículo. Las medias y los valores de P no se recalculan aquí. El vínculo del modelo es una comprobación entre la figura de la revista y los materiales oficiales.")

    add(9, "es",
        title="Hemiparesia izquierda tras un infarto de la ACM: un registro de estimulación farádica más una mano robótica",
        desc="Caso en IJPRCP: un hombre de 60 años con hemiparesia izquierda inició estimulación farádica más el Syrebo C12 unos tres meses después del ictus, cinco veces por semana durante cuatro semanas. Un caso combinado no se asigna a ninguno de los componentes.",
        lead="A una mano hemiparética a veces se le dan dos entradas a la vez: estimulación eléctrica dirigida al músculo, y una mano robótica para abrir y cerrar los dedos. Un caso de 2025 en el International Journal of Physiotherapy Research and Clinical Practice registra cuatro semanas de estimulación farádica más un Syrebo C12 en un hombre con hemiparesia izquierda. Es el registro de un plan combinado, no un ensayo de eficacia de ninguna de las dos piezas.",
        bg=[
            "Meses después del ictus, el cambio de la mano suele ser más lento, y los clínicos a veces añaden estimulación o asistencia externa a la práctica ordinaria. Una vez que se usan ambas, un cambio antes-después no puede entregarse con limpieza a ninguna de las dos.",
            "El informe sigue siendo útil. Indica cuándo empezó el plan, con qué frecuencia se aplicó y qué dispositivo estaba en la sala. No da una tasa, y no da una diferencia frente a un control.",
        ],
        device="El dispositivo robótico del informe es el Syrebo C12. La fotografía es un recorte de la página oficial de producto del C12 para que se reconozcan la consola y el guante. No añade especificaciones que el artículo omitió.",
        design="Una intervención combinada única: estimulación farádica junto con la práctica de la mano robótica Syrebo C12. No hay un grupo de control paralelo.",
        sample="Un hombre de 60 años con hemiparesia izquierda. El plan comenzó 3 meses y 2 semanas después del ictus, cinco veces por semana, durante cuatro semanas.",
        result="Esta página no reimprime puntuaciones funcionales que no se hayan comprobado contra el artículo para la columna. Lo que está claro es la organización: la estimulación y la práctica robótica se usaron juntas, así que un cambio no puede escribirse como el efecto del C12 solo o de la estimulación sola.",
        sig=[
            "El registro añade un calendario concreto: unos tres meses después del ictus, cinco sesiones por semana, dos modalidades juntas. No eleva el nivel de evidencia.",
            "Un caso de hemiparesia izquierda tras un infarto de la ACM no representa otras lesiones ni otros tiempos desde el inicio.",
        ],
        limit="Caso combinado único. El cambio no se asigna al C12 ni a la estimulación, y no es un efecto general.")

    add(10, "es",
        title="Una ortesis blanda de muñeca y mano: diseño y evaluación preliminar en Wearable Technologies",
        desc="Ledoux y Barth informan de su propia ortesis de muñeca y mano impresa en 3D en Wearable Technologies. Esta nota se queda en ese artículo de diseño. No clasifica productos comerciales y no es un ensayo de eficacia.",
        lead="En 2024 Wearable Technologies, de Cambridge University Press, publicó un artículo de diseño de Ledoux y Barth, en la Universidad Vanderbilt. El dispositivo que construyeron y evaluaron de forma preliminar es su propia ortesis de prensión de muñeca y mano impresa en 3D. El artículo menciona estructuras blandas comerciales al hablar de manos vestibles. Esta columna no convierte esa discusión en una clasificación, y no trata el artículo como evidencia de eficacia de Syrebo.",
        bg=[
            "Un dispositivo de mano que sale de la sala de terapia tiene que responder al peso, al perfil y a si una persona puede ponérselo. Los artículos de diseño suelen enunciar esas restricciones y luego describir un prototipo. No informan primero un ensayo funcional multicéntrico. Leer un artículo de diseño como un artículo de eficacia inventa criterios clínicos que no se midieron.",
            "Una estructura blanda y un exoesqueleto rígido responden a problemas de ingeniería distintos. La blandura es una forma de reducir el perfil. Hablar de cambio funcional sigue exigiendo un estudio en personas propio.",
        ],
        device="El extracto de arriba es la primera página de acceso abierto (CC BY 4.0), no una tabla de comparación. La fotografía de producto muestra un sistema clínico de guante Syrebo. No es una figura de este experimento.",
        design="Diseño, modelado y evaluación preliminar de la ortesis impresa en 3D de los propios autores. El artículo no es un ensayo aleatorizado de Syrebo ni una comparación de eficacia entre dispositivos comercializados.",
        sample="La parte con personas es una mirada preliminar al prototipo de los autores. Su tamaño y sus tareas son los del artículo. No se reformula aquí como una cohorte de Syrebo.",
        result="Esta página no cita adjetivos comerciales y no enumera otras marcas. Lo que queda es que el artículo es un estudio de diseño de acceso abierto sobre una estructura blanda y vestible. La palabra «presumably» de los autores marca la comodidad como algo que no trataron como un criterio medido.",
        sig=[
            "El artículo está en la columna para que un estudio de diseño siga siendo distinto de un ensayo de eficacia. Si una estructura blanda hace que un dispositivo sea más fácil de llevar en la vida diaria es un estudio de uso y un estudio funcional, por separado.",
            "El acceso abierto permite al lector comprobar la redacción. El sentido de comprobar es impedir que una presunción se convierta en conclusión, no elegir el producto más ligero.",
        ],
        limit="No es un ensayo de eficacia de Syrebo, ni una clasificación de productos. La fuente matiza la comodidad con «presumably». El recorte de la primera página no incluye una tabla de comparación.")

    add(11, "es",
        title="Robots de dedos pensados para el domicilio: una nota de desarrollo en el Journal of the Robotics Society of Japan",
        desc="Un artículo de 2023 del Journal of the Robotics Society of Japan trata robots de dedos de uso domiciliario para la hemiparesia y nombra a Syrebo entre los pocos ejemplos comercializados. No es un ensayo clínico.",
        lead="La rehabilitación de la mano en el domicilio se discute desde hace años. Los ejemplos comercializados en la literatura de la sociedad siguen siendo pocos. En 2023 el Journal of the Robotics Society of Japan publicó un artículo de Furudate y colegas sobre un robot de rehabilitación de los dedos pensado para el uso domiciliario tras una hemiparesia, y sobre desarrollarlo con clínicos. Los autores señalan que los casos comercializados de uso domiciliario siguen siendo raros, y nombran el guante de mano Syrebo como uno de esos casos. El artículo es una nota de desarrollo y colaboración, no un ensayo de eficacia.",
        bg=[
            "Entre la sala y el domicilio están el colocarse el dispositivo, los límites de seguridad y el uso cuando no hay un terapeuta en la habitación. Los artículos de ingeniería sitúan esas restricciones dentro del trabajo con clínicos. Ser nombrado significa que los autores eligieron este producto como ejemplo. No significa que la sociedad hiciera un estudio controlado.",
            "«Pocos se han comercializado» es también un límite. Leerlo como «la rehabilitación domiciliaria ya está disponible de forma general» convierte un ejemplo en una afirmación epidemiológica.",
        ],
        device="El artículo no imprime una fotografía del guante. La imagen del guante y la consola en esta columna es la figura 2 del caso de Cureus de 2024 de Sharma y colegas (CC BY 4.0). El pie lo dice. No es la figura original del artículo de la sociedad japonesa.",
        design="Artículo de desarrollo en una revista de sociedad, sobre robots de dedos para el uso domiciliario y sobre el trabajo con clínicos. No hay aleatorización ni comparación funcional entre grupos.",
        sample="No se aplica un tamaño de muestra clínico. El artículo discute un camino hacia un producto, no resultados en una cohorte.",
        result="El enunciado, tal como se usa aquí, es que los robots de dedos comercializados orientados al domicilio siguen siendo pocos, y que Syrebo es un ejemplo que los autores nombran. La columna mantiene ese alcance. No se reescribe como eficacia, como un puesto de mercado o como la promesa de que el entrenamiento en casa se completará.",
        sig=[
            "El valor de la nota es que el uso domiciliario se trata como un problema de ingeniería definido con clínicos. Un ejemplo comercializado muestra que un dispositivo pasó del prototipo al producto.",
            "Si puede usarse de forma segura y repetida en el domicilio sigue dependiendo de la indicación, de la supervisión y de estudios clínicos separados. El artículo de la sociedad no aporta esos datos.",
        ],
        limit="No es un ensayo clínico de Syrebo. La fuente subraya que los ejemplos comercializados siguen siendo pocos. La fotografía procede de otro caso de acceso abierto.")
